<script setup lang="ts">
import { ref,onMounted,computed } from 'vue'
import { state,refreshDashboard,notify } from '../store'
import { post } from '../api'
import Icon from '../components/Icon.vue'
import { formatSkillScore } from '../scores'
const loading=ref(true),error=ref(''),settings=ref(false),saving=ref(false),form=ref<any>({...state.user})
const data=computed(()=>state.dashboard)
onMounted(async()=>{try{await refreshDashboard()}catch(e){error.value=(e as Error).message}finally{loading.value=false}})
const week=computed(()=>Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-6+i);const key=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(date);return {key,label:['周日','周一','周二','周三','周四','周五','周六'][date.getDay()],count:data.value?.activities?.[key]||0}}))
const maximum=computed(()=>Math.max(4,...week.value.map(d=>d.count)))
const strengths=computed(()=>data.value?.abilities.filter((a:any)=>a.answer_count>0).sort((a:any,b:any)=>b.skill_score-a.skill_score).slice(0,3)||[])
async function save(){saving.value=true;try{state.user=await post('/profile',form.value);settings.value=false;notify('学习设置已保存。');await refreshDashboard()}catch(e){notify((e as Error).message,'error')}finally{saving.value=false}}
</script>
<template><div class="content-width profile-page"><header class="section-heading"><div><span class="eyebrow">每一步成长，都有迹可循</span><h1>我的成长</h1></div><button class="btn outline small" @click="form={...state.user};settings=true"><Icon name="Settings2" :size="16"/>学习设置</button></header><div v-if="error" class="error-message">{{error}}</div><div v-else-if="loading" class="loading-state"><Icon name="LoaderCircle" class="spin"/>正在整理你的成长记录…</div><template v-else-if="data"><section class="profile-identity"><span class="profile-avatar">{{state.user?.name.slice(-2)}}</span><div><h2>{{state.user?.name}}</h2><p>{{state.user?.goal}}<span class="dot-separator">·</span>每天 {{state.user?.daily_goal}} 分钟</p></div><span class="profile-joined"><Icon name="Zap" :size="17"/>累计完成 {{data.total_count}} 道题目</span></section><h2 class="profile-section-title">今天的学习</h2><div class="snapshot-grid"><article><span>完成题目数量<Icon name="CircleHelp" :size="13"/></span><b>{{data.today_count}}<small>题</small></b></article><article><span>得分率<Icon name="CircleHelp" :size="13"/></span><b>{{data.today_rate.toFixed(1)}}<small>%</small></b></article></div><section class="activity-chart"><h3>完成的题目</h3><p>{{week[0]!.key.replaceAll('-','.')}} — {{week[6]!.key.replaceAll('-','.')}}</p><div class="chart-body" role="img" :aria-label="week.map(d=>`${d.label}完成${d.count}题`).join('，')"><div class="chart-y"><span v-for="n in [4,3,2,1,0]" :key="n">{{Math.round(maximum*n/4)}}</span></div><div class="chart-grid"><div class="chart-gridlines"><i v-for="n in 5" :key="n"></i></div><div class="chart-columns"><div v-for="d in week" :key="d.key" class="chart-column"><span class="chart-value">{{d.count?d.count:''}}</span><div class="chart-bar" :style="{height:Math.max(1,d.count/maximum*100)+'%'}" :title="`${d.key}：${d.count} 题`"></div><span class="chart-label">{{d.label}}</span></div></div></div></div></section><h2 class="profile-section-title">我的学习优势</h2><section class="strength-list"><article v-for="a in strengths" :key="a.id"><span class="strength-icon"><Icon :name="a.icon" :size="23"/></span><div><h3>{{a.name}}</h3><p>已完成 <b>{{a.completed}}</b> 个关卡，技能分 <b>{{formatSkillScore(a.skill_score)}} / 10 分</b>。</p></div><RouterLink :to="'/skills/'+a.id" class="icon-button" :aria-label="`继续练习${a.name}`"><Icon name="ArrowRight" :size="19"/></RouterLink></article><article v-if="!strengths.length"><span class="strength-icon"><Icon name="Lightbulb" :size="24"/></span><div><h3>你的成长，正要开始</h3><p>提交正式训练答案后，这里会按真实正确率展示你的能力优势。</p></div><RouterLink to="/skills" class="text-button">去练习<Icon name="ArrowRight" :size="17"/></RouterLink></article><article v-if="state.user?.onboarding"><span class="strength-icon green"><Icon name="MousePointer2" :size="23"/></span><div><h3>勇于尝试</h3><p>你已经独立完成了第一枚标注，并建立了自己的学习目标。</p></div><Icon name="Check" class="earned-check" :size="22"/></article></section><h2 class="profile-section-title">收集每一次突破</h2><section class="badge-grid"><article v-for="badge in data.badges" :key="badge.id" :class="{earned:badge.earned}"><span class="badge-icon"><Icon :name="badge.icon" :size="31"/></span><h3>{{badge.name}}</h3><p>{{badge.description}}</p><small>{{badge.earned?'已获得':'等待点亮'}}</small></article></section><section v-if="data.recent_runs.length" class="recent-records"><h2 class="profile-section-title">最近的训练</h2><RouterLink v-for="r in data.recent_runs" :key="r.id" :to="'/train/'+r.id"><span class="pill" :class="r.mode==='job'?'orange':'purple'">{{r.mode==='course'?'课':r.mode==='job'?'岗':r.mode==='competition'?'赛':'入门'}}</span><div><b>{{r.mode==='onboarding'?'新手标注体验':data.abilities.find((a:any)=>a.id===r.ability_id)?.name}}</b><small>{{new Date(r.date).toLocaleString('zh-CN',{month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'})}}</small></div><strong>{{Math.round(r.score)}} 分</strong><Icon name="ChevronRight" :size="18"/></RouterLink></section></template><div v-if="settings" class="modal-backdrop" @click.self="settings=false"><form class="modal-card settings-card" role="dialog" aria-modal="true" aria-labelledby="settings-title" @submit.prevent="save"><div class="modal-title"><h2 id="settings-title">让学习更适合你</h2><button type="button" class="icon-button" @click="settings=false" aria-label="关闭设置"><Icon name="X"/></button></div><label for="display-name">显示名称</label><input id="display-name" v-model.trim="form.name" required maxlength="20"><label for="learning-goal">学习目标</label><select id="learning-goal" v-model="form.goal"><option>岗位入门</option><option>课程补强</option><option>竞赛备战</option></select><label for="daily-minutes">每日目标（分钟）</label><select id="daily-minutes" v-model.number="form.daily_goal"><option :value="5">5 分钟</option><option :value="10">10 分钟</option><option :value="20">20 分钟</option><option :value="30">30 分钟</option></select><label class="voice-toggle"><span><Icon name="Volume2" :size="18"/>答对后的语音鼓励</span><input type="checkbox" v-model="form.voice"></label><p class="settings-note">使用中文神经语音包播放简短鼓励。AI 回答仅显示文字。</p><div class="modal-actions"><button type="button" class="btn outline" @click="settings=false">取消</button><button class="btn green" :disabled="saving">{{saving?'保存中…':'保存设置'}}</button></div></form></div></div></template>
